class Oversized {
  int nested(int value) {
    if (value > 0) {
      for (var i = 0; i < value; i++) {
        while (i < value) {
          if (i.isEven) {
            if (value > 2) {
              return value;
            }
          }
          return i;
        }
      }
    }
    return 0;
  }

